INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヒヨリ", "", 1, 4, 1, "vo_empress_100101_001", 5, 100101, 0, "", 1, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "vo_empress_100101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヒヨリ", "", 2, 4, 1, "vo_empress_100101_002", 5, 100103, 0, "", 1, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "vo_empress_100101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヒヨリ", "", 3, 4, 2, "vo_empress_100101_003", 5, 100103, 0, "", 1, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "vo_empress_100101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユイ", "", 5, 4, 1, "vo_empress_100201_001", 5, 100203, 0, "", 1, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "vo_empress_100201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユイ", "", 6, 4, 1, "vo_empress_100201_002", 5, 100203, 0, "", 1, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "vo_empress_100201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユイ", "", 7, 4, 2, "vo_empress_100201_003", 5, 100203, 0, "", 1, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "vo_empress_100201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("レイ", "", 9, 4, 1, "vo_empress_100301_001", 5, 100301, 0, "", 1, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "vo_empress_100301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("レイ", "", 10, 4, 1, "vo_empress_100301_002", 5, 100303, 0, "", 1, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "vo_empress_100301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("レイ", "", 11, 4, 2, "vo_empress_100301_003", 5, 100303, 0, "", 1, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "vo_empress_100301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソギ", "", 13, 4, 1, "vo_empress_100401_001", 5, 100401, 0, "", 1, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "vo_empress_100401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソギ", "", 14, 4, 1, "vo_empress_100401_002", 5, 100401, 0, "", 1, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "vo_empress_100401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソギ", "", 15, 4, 2, "vo_empress_100401_003", 5, 100403, 0, "", 1, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "vo_empress_100401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マツリ", "", 17, 4, 1, "vo_empress_100501_001", 5, 100501, 0, "", 1, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "vo_empress_100501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マツリ", "", 18, 4, 1, "vo_empress_100501_002", 5, 100501, 0, "", 1, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "vo_empress_100501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マツリ", "", 19, 4, 2, "vo_empress_100501_003", 5, 100503, 0, "", 1, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "vo_empress_100501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アカリ", "", 21, 4, 1, "vo_empress_100601_001", 5, 100603, 0, "", 1, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "vo_empress_100601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アカリ", "", 22, 4, 1, "vo_empress_100601_002", 5, 100601, 0, "", 1, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "vo_empress_100601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アカリ", "", 23, 4, 2, "vo_empress_100601_003", 5, 100603, 0, "", 1, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "vo_empress_100601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミヤコ", "", 25, 4, 1, "vo_empress_100701_001", 5, 100701, 0, "", 1, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "vo_empress_100701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミヤコ", "", 26, 4, 1, "vo_empress_100701_002", 5, 100702, 0, "", 1, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "vo_empress_100701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミヤコ", "", 27, 4, 2, "vo_empress_100701_003", 5, 100703, 0, "", 1, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "vo_empress_100701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユキ", "", 29, 4, 1, "vo_empress_100801_001", 5, 100801, 0, "", 1, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "vo_empress_100801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユキ", "", 30, 4, 1, "vo_empress_100801_002", 5, 100801, 0, "", 1, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "vo_empress_100801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユキ", "", 31, 4, 2, "vo_empress_100801_003", 5, 100801, 0, "", 1, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "vo_empress_100801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アンナ", "", 33, 4, 1, "vo_empress_100901_001", 5, 100901, 0, "", 1, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "vo_empress_100901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アンナ", "", 34, 4, 1, "vo_empress_100901_002", 5, 100903, 0, "", 1, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "vo_empress_100901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アンナ", "", 35, 4, 2, "vo_empress_100901_003", 5, 100903, 0, "", 1, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "vo_empress_100901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マホ", "", 37, 4, 1, "vo_empress_101001_001", 5, 101001, 0, "", 1, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "vo_empress_101001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マホ", "", 38, 4, 1, "vo_empress_101001_002", 5, 101001, 0, "", 1, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "vo_empress_101001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マホ", "", 39, 4, 2, "vo_empress_101001_003", 5, 101003, 0, "", 1, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "vo_empress_101001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リノ", "", 41, 4, 1, "vo_empress_101101_001", 5, 101101, 0, "", 1, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "vo_empress_101101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リノ", "", 42, 4, 1, "vo_empress_101101_002", 5, 101101, 0, "", 1, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "vo_empress_101101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リノ", "", 43, 4, 2, "vo_empress_101101_003", 5, 101103, 0, "", 1, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "vo_empress_101101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ハツネ", "", 45, 4, 1, "vo_empress_101201_001", 5, 101201, 0, "", 1, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "vo_empress_101201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ハツネ", "", 46, 4, 1, "vo_empress_101201_002", 5, 101202, 0, "", 1, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "vo_empress_101201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ハツネ", "", 47, 4, 2, "vo_empress_101201_003", 5, 101203, 0, "", 1, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "vo_empress_101201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナナカ", "", 49, 4, 1, "vo_empress_101301_001", 5, 101301, 0, "", 1, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "vo_empress_101301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナナカ", "", 50, 4, 1, "vo_empress_101301_002", 5, 101301, 0, "", 1, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "vo_empress_101301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナナカ", "", 51, 4, 2, "vo_empress_101301_003", 5, 101303, 0, "", 1, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "vo_empress_101301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カスミ", "", 53, 4, 1, "vo_empress_101401_001", 5, 101401, 0, "", 1, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "vo_empress_101401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カスミ", "", 54, 4, 1, "vo_empress_101401_002", 5, 101401, 0, "", 1, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "vo_empress_101401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カスミ", "", 55, 4, 2, "vo_empress_101401_003", 5, 101403, 0, "", 1, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "vo_empress_101401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミサト", "", 57, 4, 1, "vo_empress_101501_001", 5, 101501, 0, "", 1, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "vo_empress_101501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミサト", "", 58, 4, 1, "vo_empress_101501_002", 5, 101501, 0, "", 1, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "vo_empress_101501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミサト", "", 59, 4, 2, "vo_empress_101501_003", 5, 101501, 0, "", 1, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "vo_empress_101501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("スズナ", "", 61, 4, 1, "vo_empress_101601_001", 5, 101601, 0, "", 1, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "vo_empress_101601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("スズナ", "", 62, 4, 1, "vo_empress_101601_002", 5, 101601, 0, "", 1, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "vo_empress_101601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("スズナ", "", 63, 4, 2, "vo_empress_101601_003", 5, 101601, 0, "", 1, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "vo_empress_101601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カオリ", "", 65, 4, 1, "vo_empress_101701_001", 5, 101701, 0, "", 1, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "vo_empress_101701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カオリ", "", 66, 4, 1, "vo_empress_101701_002", 5, 101701, 0, "", 1, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "vo_empress_101701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カオリ", "", 67, 4, 2, "vo_empress_101701_003", 5, 101703, 0, "", 1, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "vo_empress_101701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イオ", "", 69, 4, 1, "vo_empress_101801_001", 5, 101801, 0, "", 1, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "vo_empress_101801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イオ", "", 70, 4, 1, "vo_empress_101801_002", 5, 101801, 0, "", 1, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "vo_empress_101801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イオ", "", 71, 4, 2, "vo_empress_101801_003", 5, 101803, 0, "", 1, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "vo_empress_101801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミミ", "", 73, 4, 1, "vo_empress_102001_001", 5, 102003, 0, "", 1, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "vo_empress_102001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミミ", "", 74, 4, 1, "vo_empress_102001_002", 5, 102003, 0, "", 1, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "vo_empress_102001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミミ", "", 75, 4, 2, "vo_empress_102001_003", 5, 102003, 0, "", 1, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "vo_empress_102001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クルミ", "", 77, 4, 1, "vo_empress_102101_001", 5, 102101, 0, "", 1, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "vo_empress_102101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クルミ", "", 78, 4, 1, "vo_empress_102101_002", 5, 102101, 0, "", 1, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "vo_empress_102101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クルミ", "", 79, 4, 2, "vo_empress_102101_003", 5, 102101, 0, "", 1, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "vo_empress_102101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヨリ", "", 81, 4, 1, "vo_empress_102201_001", 5, 102201, 0, "", 1, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "vo_empress_102201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヨリ", "", 82, 4, 1, "vo_empress_102201_002", 5, 102201, 0, "", 1, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "vo_empress_102201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヨリ", "", 83, 4, 2, "vo_empress_102201_003", 5, 102203, 0, "", 1, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "vo_empress_102201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アヤネ", "", 85, 4, 1, "vo_empress_102301_001", 5, 102301, 0, "", 1, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "vo_empress_102301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アヤネ", "", 86, 4, 1, "vo_empress_102301_002", 5, 102303, 0, "", 1, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "vo_empress_102301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アヤネ", "", 87, 4, 2, "vo_empress_102301_003", 5, 102303, 0, "", 1, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "vo_empress_102301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("スズメ", "", 89, 4, 1, "vo_empress_102501_001", 5, 102503, 0, "", 1, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "vo_empress_102501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("スズメ", "", 90, 4, 1, "vo_empress_102501_002", 5, 102503, 0, "", 1, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "vo_empress_102501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("スズメ", "", 91, 4, 2, "vo_empress_102501_003", 5, 102503, 0, "", 1, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "vo_empress_102501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リン", "", 93, 4, 1, "vo_empress_102601_001", 5, 102603, 0, "", 1, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "vo_empress_102601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リン", "", 94, 4, 1, "vo_empress_102601_002", 5, 102603, 0, "", 1, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "vo_empress_102601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リン", "", 95, 4, 2, "vo_empress_102601_003", 5, 102603, 0, "", 1, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "vo_empress_102601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("エリコ", "", 97, 4, 1, "vo_empress_102701_001", 5, 102701, 0, "", 1, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "vo_empress_102701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("エリコ", "", 98, 4, 1, "vo_empress_102701_002", 5, 102701, 0, "", 1, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "vo_empress_102701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("エリコ", "", 99, 4, 2, "vo_empress_102701_003", 5, 102703, 0, "", 1, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "vo_empress_102701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("サレン", "", 101, 4, 1, "vo_empress_102801_001", 5, 102801, 0, "", 1, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "vo_empress_102801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("サレン", 1, 102, 4, 4002, "vo_empress_102801_002", 3, 102801, 0, 10000, 1, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", "vo_empress_102801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("サレン", "", 103, 4, 2, "vo_empress_102801_003", 5, 102803, 0, "", 1, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "vo_empress_102801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ノゾミ", "", 105, 4, 1, "vo_empress_102901_001", 5, 102903, 0, "", 1, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "vo_empress_102901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ノゾミ", "", 106, 4, 1, "vo_empress_102901_002", 5, 102903, 0, "", 1, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "vo_empress_102901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ノゾミ", "", 107, 4, 2, "vo_empress_102901_003", 5, 102903, 0, "", 1, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "vo_empress_102901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ニノン", "", 109, 4, 1, "vo_empress_103001_001", 5, 103001, 0, "", 1, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "vo_empress_103001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ニノン", "", 110, 4, 1, "vo_empress_103001_002", 5, 103001, 0, "", 1, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "vo_empress_103001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ニノン", "", 111, 4, 2, "vo_empress_103001_003", 5, 103003, 0, "", 1, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "vo_empress_103001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シノブ", "", 113, 4, 1, "vo_empress_103101_001", 5, 103101, 0, "", 1, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "vo_empress_103101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シノブ", "", 114, 4, 1, "vo_empress_103101_002", 5, 103101, 0, "", 1, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "vo_empress_103101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シノブ", "", 115, 4, 2, "vo_empress_103101_003", 5, 103103, 0, "", 1, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "vo_empress_103101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アキノ", "", 117, 4, 1, "vo_empress_103201_001", 5, 103201, 0, "", 1, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "vo_empress_103201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アキノ", "", 118, 4, 1, "vo_empress_103201_002", 5, 103201, 0, "", 1, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "vo_empress_103201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アキノ", "", 119, 4, 2, "vo_empress_103201_003", 5, 103203, 0, "", 1, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "vo_empress_103201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マヒル", "", 121, 4, 1, "vo_empress_103301_001", 5, 103301, 0, "", 1, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "vo_empress_103301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マヒル", "", 122, 4, 1, "vo_empress_103301_002", 5, 103301, 0, "", 1, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "vo_empress_103301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マヒル", "", 123, 4, 2, "vo_empress_103301_003", 5, 103303, 0, "", 1, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "vo_empress_103301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユカリ", "", 125, 4, 1, "vo_empress_103401_001", 5, 103401, 0, "", 1, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "vo_empress_103401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユカリ", "", 126, 4, 1, "vo_empress_103401_002", 5, 103401, 0, "", 1, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "vo_empress_103401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユカリ", "", 127, 4, 2, "vo_empress_103401_003", 5, 103403, 0, "", 1, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "vo_empress_103401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("キョウカ", "", 129, 4, 1, "vo_empress_103601_001", 5, 103603, 0, "", 1, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "vo_empress_103601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("キョウカ", "", 130, 4, 1, "vo_empress_103601_002", 5, 103603, 0, "", 1, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "vo_empress_103601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("キョウカ", "", 131, 4, 2, "vo_empress_103601_003", 5, 103601, 0, "", 1, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "vo_empress_103601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("トモ", "", 133, 4, 1, "vo_empress_103701_001", 5, 103701, 0, "", 1, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "vo_empress_103701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("トモ", "", 134, 4, 1, "vo_empress_103701_002", 5, 103701, 0, "", 1, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "vo_empress_103701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("トモ", "", 135, 4, 2, "vo_empress_103701_003", 5, 103701, 0, "", 1, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "vo_empress_103701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シオリ", "", 137, 4, 1, "vo_empress_103801_001", 5, 103801, 0, "", 1, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "vo_empress_103801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シオリ", "", 138, 4, 1, "vo_empress_103801_002", 5, 103801, 0, "", 1, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "vo_empress_103801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シオリ", "", 139, 4, 2, "vo_empress_103801_003", 5, 103803, 0, "", 1, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "vo_empress_103801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アオイ", "", 141, 4, 1, "vo_empress_104001_001", 5, 104001, 0, "", 1, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "vo_empress_104001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アオイ", "", 142, 4, 1, "vo_empress_104001_002", 5, 104002, 0, "", 1, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "vo_empress_104001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アオイ", "", 143, 4, 2, "vo_empress_104001_003", 5, 104003, 0, "", 1, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "vo_empress_104001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("チカ", "", 145, 4, 1, "vo_empress_104201_001", 5, 104203, 0, "", 1, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "vo_empress_104201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("チカ", "", 146, 4, 1, "vo_empress_104201_002", 5, 104201, 0, "", 1, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "vo_empress_104201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("チカ", "", 147, 4, 2, "vo_empress_104201_003", 5, 104203, 0, "", 1, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "vo_empress_104201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マコト", "", 149, 4, 1, "vo_empress_104301_001", 5, 104301, 0, "", 1, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "vo_empress_104301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マコト", "", 150, 4, 1, "vo_empress_104301_002", 5, 104301, 0, "", 1, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "vo_empress_104301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("マコト", "", 151, 4, 2, "vo_empress_104301_003", 5, 104303, 0, "", 1, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "vo_empress_104301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イリヤ", "", 153, 4, 1, "vo_empress_104401_001", 5, 104401, 0, "", 1, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "vo_empress_104401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イリヤ", "", 154, 4, 1, "vo_empress_104401_002", 5, 104401, 0, "", 1, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "vo_empress_104401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イリヤ", "", 155, 4, 2, "vo_empress_104401_003", 5, 104401, 0, "", 1, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "vo_empress_104401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クウカ", "", 157, 4, 1, "vo_empress_104501_001", 5, 104501, 0, "", 1, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "vo_empress_104501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クウカ", "", 158, 4, 1, "vo_empress_104501_002", 5, 104501, 0, "", 1, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "vo_empress_104501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クウカ", "", 159, 4, 2, "vo_empress_104501_003", 5, 104503, 0, "", 1, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "vo_empress_104501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("タマキ", "", 161, 4, 1, "vo_empress_104601_001", 5, 104601, 0, "", 1, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "vo_empress_104601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("タマキ", "", 162, 4, 1, "vo_empress_104601_002", 5, 104601, 0, "", 1, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "vo_empress_104601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("タマキ", "", 163, 4, 2, "vo_empress_104601_003", 5, 104603, 0, "", 1, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "vo_empress_104601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ジュン", "", 165, 4, 1, "vo_empress_104701_001", 5, 104701, 0, "", 1, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "vo_empress_104701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ジュン", "", 166, 4, 1, "vo_empress_104701_002", 5, 104701, 0, "", 1, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "vo_empress_104701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ジュン", "", 167, 4, 2, "vo_empress_104701_003", 5, 104701, 0, "", 1, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "vo_empress_104701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミフユ", "", 169, 4, 1, "vo_empress_104801_001", 5, 104801, 0, "", 1, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "vo_empress_104801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミフユ", "", 170, 4, 1, "vo_empress_104801_002", 5, 104801, 0, "", 1, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "vo_empress_104801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミフユ", "", 171, 4, 2, "vo_empress_104801_003", 5, 104803, 0, "", 1, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "vo_empress_104801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シズル", "", 173, 4, 1, "vo_empress_104901_001", 5, 104902, 0, "", 1, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "vo_empress_104901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シズル", "", 174, 4, 1, "vo_empress_104901_002", 5, 104902, 0, "", 1, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "vo_empress_104901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シズル", "", 175, 4, 2, "vo_empress_104901_003", 5, 104903, 0, "", 1, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "vo_empress_104901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミサキ", "", 177, 4, 1, "vo_empress_105001_001", 5, 105001, 0, "", 1, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "vo_empress_105001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミサキ", "", 178, 4, 1, "vo_empress_105001_002", 5, 105001, 0, "", 1, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "vo_empress_105001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミサキ", "", 179, 4, 2, "vo_empress_105001_003", 5, 105003, 0, "", 1, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "vo_empress_105001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミツキ", "", 181, 4, 1, "vo_empress_105101_001", 5, 105101, 0, "", 1, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "vo_empress_105101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミツキ", "", 182, 4, 1, "vo_empress_105101_002", 5, 105101, 0, "", 1, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "vo_empress_105101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミツキ", "", 183, 4, 2, "vo_empress_105101_003", 5, 105101, 0, "", 1, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "vo_empress_105101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リマ", "", 185, 4, 1, "vo_empress_105201_001", 5, 105201, 0, "", 1, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "vo_empress_105201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リマ", 1, 186, 4, 4002, "vo_empress_105201_002", 3, 105201, 0, 10000, 1, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", "vo_empress_105201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リマ", "", 187, 4, 2, "vo_empress_105201_003", 5, 105201, 0, "", 1, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "vo_empress_105201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("モニカ", "", 189, 4, 1, "vo_empress_105301_001", 5, 105303, 0, "", 1, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "vo_empress_105301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("モニカ", "", 190, 4, 1, "vo_empress_105301_002", 5, 105301, 0, "", 1, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "vo_empress_105301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("モニカ", "", 191, 4, 2, "vo_empress_105301_003", 5, 105301, 0, "", 1, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "vo_empress_105301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ツムギ", "", 193, 4, 1, "vo_empress_105401_001", 5, 105401, 0, "", 1, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "vo_empress_105401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ツムギ", 1, 194, 4, 4002, "vo_empress_105401_002", 3, 105403, 0, 10000, 1, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", "vo_empress_105401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ツムギ", "", 195, 4, 2, "vo_empress_105401_003", 5, 105403, 0, "", 1, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "vo_empress_105401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アユミ", "", 197, 4, 1, "vo_empress_105501_001", 5, 105503, 0, "", 1, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "vo_empress_105501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アユミ", "", 198, 4, 1, "vo_empress_105501_002", 5, 105501, 0, "", 1, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "vo_empress_105501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アユミ", "", 199, 4, 2, "vo_empress_105501_003", 5, 105503, 0, "", 1, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "vo_empress_105501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルカ", "", 201, 4, 1, "vo_empress_105601_001", 5, 105601, 0, "", 1, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "vo_empress_105601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルカ", "", 202, 4, 1, "vo_empress_105601_002", 5, 105601, 0, "", 1, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "vo_empress_105601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルカ", "", 203, 4, 2, "vo_empress_105601_003", 5, 105603, 0, "", 1, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "vo_empress_105601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ペコリーヌ", "", 205, 4, 1, "vo_empress_105801_001", 5, 105803, 0, "", 1, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "vo_empress_105801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ペコリーヌ", 1, 206, 4, 4003, "vo_empress_105801_002", 3, 105801, 0, 10000, 1, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", "vo_empress_105801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ペコリーヌ", "", 207, 4, 2, "vo_empress_105801_003", 5, 105803, 0, "", 1, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "vo_empress_105801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("コッコロ", "", 209, 4, 1, "vo_empress_105901_001", 5, 105903, 0, "", 1, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "vo_empress_105901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("コッコロ", "", 210, 4, 1, "vo_empress_105901_002", 5, 105905, 0, "", 1, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "vo_empress_105901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("コッコロ", "", 211, 4, 2, "vo_empress_105901_003", 5, 105903, 0, "", 1, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "vo_empress_105901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("キャル", 1, 213, 4, 4005, "vo_empress_106001_001", 3, 106001, 0, 10000, 1, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", "vo_empress_106001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("キャル", "", 214, 4, 1, "vo_empress_106001_002", 5, 106003, 0, "", 1, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "vo_empress_106001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("キャル", "", 215, 4, 2, "vo_empress_106001_003", 5, 106003, 0, "", 1, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "vo_empress_106001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ノウェム", "", 217, 4, 1, "vo_empress_106101_001", 5, 106102, 0, "", 1, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "vo_empress_106101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ノウェム", "", 218, 4, 1, "vo_empress_106101_002", 5, 106101, 0, "", 1, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "vo_empress_106101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ノウェム", "", 219, 4, 2, "vo_empress_106101_003", 5, 106103, 0, "", 1, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "vo_empress_106101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シェフィ", "", 221, 4, 1, "vo_empress_106401_001", 5, 106401, 0, "", 1, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "vo_empress_106401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シェフィ", 1, 222, 4, 4004, "vo_empress_106401_002", 3, 106403, 0, 10000, 1, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", "vo_empress_106401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シェフィ", "", 223, 4, 2, "vo_empress_106401_003", 5, 106401, 0, "", 1, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "vo_empress_106401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カヤ", "", 225, 4, 1, "vo_empress_106501_001", 5, 106501, 0, "", 1, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "vo_empress_106501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カヤ", "", 226, 4, 1, "vo_empress_106501_002", 5, 106501, 0, "", 1, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "vo_empress_106501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カヤ", "", 227, 4, 2, "vo_empress_106501_003", 5, 106503, 0, "", 1, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "vo_empress_106501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イノリ", "", 229, 4, 1, "vo_empress_106601_001", 5, 106603, 0, "", 1, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "vo_empress_106601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イノリ", "", 230, 4, 1, "vo_empress_106601_002", 5, 106601, 0, "", 1, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "vo_empress_106601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イノリ", "", 231, 4, 2, "vo_empress_106601_003", 5, 106603, 0, "", 1, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "vo_empress_106601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ホマレ", "", 233, 4, 1, "vo_empress_106701_001", 5, 106701, 0, "", 1, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "vo_empress_106701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ホマレ", "", 234, 4, 1, "vo_empress_106701_002", 5, 106701, 0, "", 1, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "vo_empress_106701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ホマレ", "", 235, 4, 2, "vo_empress_106701_003", 5, 106703, 0, "", 1, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "vo_empress_106701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ラビリスタ", "", 237, 4, 1, "vo_empress_106801_001", 5, 106802, 0, "", 1, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "vo_empress_106801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ラビリスタ", 1, 238, 4, 4005, "vo_empress_106801_002", 3, 106801, 0, 10000, 1, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", "vo_empress_106801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ラビリスタ", "", 239, 4, 2, "vo_empress_106801_003", 5, 106801, 0, "", 1, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "vo_empress_106801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネネカ", 1, 241, 4, 4005, "vo_empress_107001_001", 3, 107001, 0, 10000, 1, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", "vo_empress_107001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネネカ", "", 242, 4, 1, "vo_empress_107001_002", 5, 107001, 0, "", 1, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "vo_empress_107001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネネカ", "", 243, 4, 2, "vo_empress_107001_003", 5, 107001, 0, "", 1, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "vo_empress_107001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリスティーナ", "", 245, 4, 1, "vo_empress_107101_001", 5, 107101, 0, "", 1, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "vo_empress_107101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリスティーナ", 1, 246, 4, 4005, "vo_empress_107101_002", 3, 107101, 0, 10000, 1, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", "vo_empress_107101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリスティーナ", "", 247, 4, 2, "vo_empress_107101_003", 5, 107103, 0, "", 1, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "vo_empress_107101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クロエ", "", 249, 4, 1, "vo_empress_110801_001", 5, 110801, 0, "", 1, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "vo_empress_110801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クロエ", 1, 250, 4, 4005, "vo_empress_110801_002", 3, 110801, 0, 10000, 1, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", "vo_empress_110801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クロエ", "", 251, 4, 2, "vo_empress_110801_003", 5, 110803, 0, "", 1, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "vo_empress_110801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("チエル", "", 253, 4, 1, "vo_empress_110901_001", 5, 110901, 0, "", 1, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "vo_empress_110901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("チエル", "", 254, 4, 1, "vo_empress_110901_002", 5, 110901, 0, "", 1, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "vo_empress_110901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("チエル", "", 255, 4, 2, "vo_empress_110901_003", 5, 110903, 0, "", 1, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "vo_empress_110901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユニ", "", 257, 4, 1, "vo_empress_111001_001", 5, 111001, 0, "", 1, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "vo_empress_111001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユニ", "", 258, 4, 1, "vo_empress_111001_002", 5, 111001, 0, "", 1, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "vo_empress_111001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユニ", "", 259, 4, 2, "vo_empress_111001_003", 5, 111003, 0, "", 1, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "vo_empress_111001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クレジッタ", "", 261, 4, 1, "vo_empress_118001_001", 5, 118001, 0, "", 1, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "vo_empress_118001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クレジッタ", "", 262, 4, 1, "vo_empress_118001_002", 5, 118003, 0, "", 1, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "vo_empress_118001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クレジッタ", "", 263, 4, 2, "vo_empress_118001_003", 5, 118003, 0, "", 1, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "vo_empress_118001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ランファ", "", 265, 4, 1, "vo_empress_118101_001", 5, 118101, 0, "", 1, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "vo_empress_118101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ランファ", "", 266, 4, 1, "vo_empress_118101_002", 5, 118101, 0, "", 1, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "vo_empress_118101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ランファ", "", 267, 4, 2, "vo_empress_118101_003", 5, 118103, 0, "", 1, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "vo_empress_118101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソラ", 1, 269, 4, 4005, "vo_empress_118201_001", 3, 118201, 0, 10000, 1, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", "vo_empress_118201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソラ", "", 270, 4, 1, "vo_empress_118201_002", 5, 118201, 0, "", 1, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "vo_empress_118201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ミソラ", "", 271, 4, 2, "vo_empress_118201_003", 5, 118202, 0, "", 1, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "vo_empress_118201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カリン", "", 273, 4, 1, "vo_empress_118501_001", 5, 118501, 0, "", 1, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "vo_empress_118501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カリン", "", 274, 4, 1, "vo_empress_118501_002", 5, 118502, 0, "", 1, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "vo_empress_118501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カリン", "", 275, 4, 2, "vo_empress_118501_003", 5, 118503, 0, "", 1, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "vo_empress_118501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネビア", "", 277, 4, 1, "vo_empress_118601_001", 5, 118601, 0, "", 1, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "vo_empress_118601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネビア", "", 278, 4, 1, "vo_empress_118601_002", 5, 118601, 0, "", 1, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "vo_empress_118601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネビア", "", 279, 4, 2, "vo_empress_118601_003", 5, 118603, 0, "", 1, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "vo_empress_118601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴァンピィ", "", 281, 4, 1, "vo_empress_122301_001", 5, 122303, 0, "", 1, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "vo_empress_122301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴァンピィ", "", 282, 4, 1, "vo_empress_122301_002", 5, 122302, 0, "", 1, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "vo_empress_122301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴァンピィ", "", 283, 4, 2, "vo_empress_122301_003", 5, 122303, 0, "", 1, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "vo_empress_122301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アメス", "", 285, 4, 1, "vo_empress_123001_001", 5, 123002, 0, "", 1, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "vo_empress_123001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アメス", "", 286, 4, 1, "vo_empress_123001_002", 5, 123001, 0, "", 1, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "vo_empress_123001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アメス", "", 287, 4, 2, "vo_empress_123001_003", 5, 123003, 0, "", 1, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "vo_empress_123001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネア", "", 289, 4, 1, "vo_empress_123301_001", 5, 123301, 0, "", 1, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "vo_empress_123301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネア", "", 290, 4, 1, "vo_empress_123301_002", 5, 123301, 0, "", 1, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "vo_empress_123301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネア", "", 291, 4, 2, "vo_empress_123301_003", 5, 123303, 0, "", 1, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "vo_empress_123301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クローチェ", "", 293, 4, 1, "vo_empress_126401_001", 5, 126401, 0, "", 1, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "vo_empress_126401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クローチェ", "", 294, 4, 1, "vo_empress_126401_002", 5, 126401, 0, "", 1, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "vo_empress_126401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クローチェ", "", 295, 4, 2, "vo_empress_126401_003", 5, 126403, 0, "", 1, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "vo_empress_126401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ライラエル", "", 297, 4, 1, "vo_empress_126501_001", 5, 126501, 0, "", 1, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "vo_empress_126501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ライラエル", 1, 298, 4, 4002, "vo_empress_126501_002", 3, 126506, 0, 10000, 1, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", "vo_empress_126501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ライラエル", "", 299, 4, 2, "vo_empress_126501_003", 5, 126503, 0, "", 1, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "vo_empress_126501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リンド", 1, 301, 4, 4002, "vo_empress_127701_001", 3, 127701, 0, 10000, 1, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", "vo_empress_127701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リンド", "", 302, 4, 1, "vo_empress_127701_002", 5, 127701, 0, "", 1, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "vo_empress_127701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リンド", "", 303, 4, 2, "vo_empress_127701_003", 5, 127703, 0, "", 1, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "vo_empress_127701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴルム", "", 305, 4, 1, "vo_empress_127801_001", 5, 127801, 0, "", 1, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "vo_empress_127801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴルム", 1, 306, 4, 4002, "vo_empress_127801_002", 3, 127801, 0, 10000, 1, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", "vo_empress_127801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴルム", "", 307, 4, 2, "vo_empress_127801_003", 5, 127803, 0, "", 1, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "vo_empress_127801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("エリス", 1, 309, 4, 4005, "vo_empress_129001_001", 3, 129001, 0, 10000, 1, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", "vo_empress_129001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("エリス", "", 310, 4, 1, "vo_empress_129001_002", 5, 129001, 0, "", 1, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "vo_empress_129001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("エリス", "", 311, 4, 2, "vo_empress_129001_003", 5, 129003, 0, "", 1, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "vo_empress_129001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アネモネ", "", 313, 4, 1, "vo_empress_129601_001", 5, 129601, 0, "", 1, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "vo_empress_129601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アネモネ", "", 314, 4, 1, "vo_empress_129601_002", 5, 129601, 0, "", 1, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "vo_empress_129601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アネモネ", "", 315, 4, 2, "vo_empress_129601_003", 5, 129603, 0, "", 1, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "vo_empress_129601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネフィ＝ネラ", "", 317, 4, 1, "vo_empress_129701_001", 5, 129701, 0, "", 1, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "vo_empress_129701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネフィ＝ネラ", "", 318, 4, 1, "vo_empress_129701_002", 5, 129701, 0, "", 1, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "vo_empress_129701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ネフィ＝ネラ", "", 319, 4, 2, "vo_empress_129701_003", 5, 129703, 0, "", 1, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "vo_empress_129701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヤマト", 1, 321, 4, 4003, "vo_empress_130001_001", 3, 130001, 0, 10000, 1, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", "vo_empress_130001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヤマト", "", 322, 4, 1, "vo_empress_130001_002", 5, 130001, 0, "", 1, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "vo_empress_130001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヤマト", "", 323, 4, 2, "vo_empress_130001_003", 5, 130003, 0, "", 1, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "vo_empress_130001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ワカナ", "", 325, 4, 1, "vo_empress_130101_001", 5, 130101, 0, "", 1, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "vo_empress_130101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ワカナ", "", 326, 4, 1, "vo_empress_130101_002", 5, 130101, 0, "", 1, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "vo_empress_130101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ワカナ", "", 327, 4, 2, "vo_empress_130101_003", 5, 130103, 0, "", 1, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "vo_empress_130101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("フブキ", "", 329, 4, 1, "vo_empress_130201_001", 5, 130201, 0, "", 1, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "vo_empress_130201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("フブキ", "", 330, 4, 1, "vo_empress_130201_002", 5, 130201, 0, "", 1, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "vo_empress_130201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("フブキ", "", 331, 4, 2, "vo_empress_130201_003", 5, 130203, 0, "", 1, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "vo_empress_130201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クルル", "", 333, 4, 1, "vo_empress_130901_001", 5, 130901, 0, "", 1, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "vo_empress_130901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クルル", "", 334, 4, 1, "vo_empress_130901_002", 5, 130901, 0, "", 1, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "vo_empress_130901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クルル", "", 335, 4, 2, "vo_empress_130901_003", 5, 130903, 0, "", 1, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "vo_empress_130901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルイズマリー", "", 337, 4, 1, "vo_empress_132301_001", 5, 132301, 0, "", 1, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "vo_empress_132301_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルイズマリー", "", 338, 4, 1, "vo_empress_132301_002", 5, 132301, 0, "", 1, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "vo_empress_132301_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルイズマリー", "", 339, 4, 2, "vo_empress_132301_003", 5, 132303, 0, "", 1, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "vo_empress_132301_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イロハ", "", 341, 4, 1, "vo_empress_132401_001", 5, 132401, 0, "", 1, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "vo_empress_132401_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イロハ", "", 342, 4, 1, "vo_empress_132401_002", 5, 132401, 0, "", 1, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "vo_empress_132401_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("イロハ", "", 343, 4, 2, "vo_empress_132401_003", 5, 132401, 0, "", 1, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "vo_empress_132401_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ソノ", "", 345, 4, 1, "vo_empress_132501_001", 5, 132501, 0, "", 1, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "vo_empress_132501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ソノ", "", 346, 4, 1, "vo_empress_132501_002", 5, 132501, 0, "", 1, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "vo_empress_132501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ソノ", "", 347, 4, 2, "vo_empress_132501_003", 5, 132503, 0, "", 1, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "vo_empress_132501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("グレイス", "", 349, 4, 1, "vo_empress_133001_001", 5, 133001, 0, "", 1, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "vo_empress_133001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("グレイス", 1, 350, 4, 4001, "vo_empress_133001_002", 3, 133003, 0, 10000, 1, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", "vo_empress_133001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("グレイス", "", 351, 4, 2, "vo_empress_133001_003", 5, 133003, 0, "", 1, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "vo_empress_133001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴァイオレット", "", 353, 4, 1, "vo_empress_133101_001", 5, 133101, 0, "", 1, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "vo_empress_133101_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴァイオレット", 1, 354, 4, 4001, "vo_empress_133101_002", 3, 133101, 0, 10000, 1, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", "vo_empress_133101_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ヴァイオレット", "", 355, 4, 2, "vo_empress_133101_003", 5, 133103, 0, "", 1, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "vo_empress_133101_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("メドゥーサ", "", 357, 4, 1, "vo_empress_133601_001", 5, 133601, 0, "", 1, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "vo_empress_133601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("メドゥーサ", "", 358, 4, 1, "vo_empress_133601_002", 5, 133601, 0, "", 1, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "vo_empress_133601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("メドゥーサ", "", 359, 4, 2, "vo_empress_133601_003", 5, 133603, 0, "", 1, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "vo_empress_133601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ホウオウ", "", 361, 4, 1, "vo_empress_134701_001", 5, 134701, 0, "", 1, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "vo_empress_134701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ホウオウ", "", 362, 4, 1, "vo_empress_134701_002", 5, 134701, 0, "", 1, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "vo_empress_134701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ホウオウ", "", 363, 4, 2, "vo_empress_134701_003", 5, 134703, 0, "", 1, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "vo_empress_134701_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カノン", "", 365, 4, 1, "vo_empress_134901_001", 5, 134901, 0, "", 1, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "vo_empress_134901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カノン", "", 366, 4, 1, "vo_empress_134901_002", 5, 134901, 0, "", 1, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "vo_empress_134901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("カノン", "", 367, 4, 2, "vo_empress_134901_003", 5, 134903, 0, "", 1, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "vo_empress_134901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アイラ", "", 369, 4, 1, "vo_empress_135501_001", 5, 135501, 0, "", 1, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "vo_empress_135501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アイラ", 1, 370, 4, 4005, "vo_empress_135501_002", 3, 135501, 0, 10000, 1, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", "vo_empress_135501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アイラ", "", 371, 4, 2, "vo_empress_135501_003", 5, 135503, 0, "", 1, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "vo_empress_135501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シナツ", "", 373, 4, 1, "vo_empress_135601_001", 5, 135601, 0, "", 1, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "vo_empress_135601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シナツ", "", 374, 4, 1, "vo_empress_135601_002", 5, 135601, 0, "", 1, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "vo_empress_135601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("シナツ", "", 375, 4, 2, "vo_empress_135601_003", 5, 135603, 0, "", 1, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "vo_empress_135601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユキノ", 1, 377, 4, 4001, "vo_empress_135801_001", 3, 135801, 0, 10000, 1, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", "vo_empress_135801_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユキノ", "", 378, 4, 1, "vo_empress_135801_002", 5, 135801, 0, "", 1, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "vo_empress_135801_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ユキノ", "", 379, 4, 2, "vo_empress_135801_003", 5, 135803, 0, "", 1, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "vo_empress_135801_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("サツキ", 1, 381, 4, 4001, "vo_empress_135901_001", 3, 135903, 0, 10000, 1, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", "vo_empress_135901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("サツキ", "", 382, 4, 1, "vo_empress_135901_002", 5, 135901, 0, "", 1, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "vo_empress_135901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("サツキ", "", 383, 4, 2, "vo_empress_135901_003", 5, 135901, 0, "", 1, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "vo_empress_135901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アラクネ", "", 385, 4, 1, "vo_empress_136001_001", 5, 136001, 0, "", 1, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "vo_empress_136001_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アラクネ", 1, 386, 4, 4003, "vo_empress_136001_002", 3, 136001, 0, 10000, 1, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", "vo_empress_136001_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("アラクネ", "", 387, 4, 2, "vo_empress_136001_003", 5, 136003, 0, "", 1, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "vo_empress_136001_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナーナ", "", 389, 4, 1, "vo_empress_136201_001", 5, 136201, 0, "", 1, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "vo_empress_136201_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナーナ", "", 390, 4, 1, "vo_empress_136201_002", 5, 136201, 0, "", 1, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "vo_empress_136201_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ナーナ", "", 391, 4, 2, "vo_empress_136201_003", 5, 136201, 0, "", 1, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "vo_empress_136201_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルルィ", 1, 393, 4, 4001, "vo_empress_136901_001", 3, 136903, 0, 10000, 1, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", "vo_empress_136901_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルルィ", "", 394, 4, 1, "vo_empress_136901_002", 5, 136901, 0, "", 1, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "vo_empress_136901_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("ルルィ", "", 395, 4, 2, "vo_empress_136901_003", 5, 136903, 0, "", 1, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "vo_empress_136901_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リリ", "", 397, 4, 1, "vo_empress_139501_001", 5, 139501, 0, "", 1, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "vo_empress_139501_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リリ", 1, 398, 4, 4002, "vo_empress_139501_002", 3, 139503, 0, 10000, 1, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", "vo_empress_139501_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("リリ", "", 399, 4, 2, "vo_empress_139501_003", 5, 139503, 0, "", 1, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "vo_empress_139501_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリア", "", 401, 4, 1, "vo_empress_139601_001", 5, 139603, 0, "", 1, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "vo_empress_139601_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリア", 1, 402, 4, 4002, "vo_empress_139601_002", 3, 139603, 0, 10000, 1, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", "vo_empress_139601_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("クリア", "", 403, 4, 2, "vo_empress_139601_003", 5, 139603, 0, "", 1, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "vo_empress_139601_003");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("プレシア", "", 405, 4, 1, "vo_empress_139701_001", 5, 139701, 0, "", 1, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "vo_empress_139701_001");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("プレシア", "", 406, 4, 1, "vo_empress_139701_002", 5, 139701, 0, "", 1, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "vo_empress_139701_002");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("プレシア", "", 407, 4, 2, "vo_empress_139701_003", 5, 139703, 0, "", 1, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "vo_empress_139701_003");
